scriptData.script:
let roll = Math.ceil(CONFIG.Dice.randomUniform() * 10)
let effectName = ""
if (roll <= 4)
{
  effectName = "Extra Eye";
}
else if (roll <= 7)
{
  effectName = "Extra Limb";
}
else if (roll <= 10)
{
  effectName = "Grasping Tentacle";
}

let effect = this.item.effects.getName(effectName);
this.actor.applyEffect({effects: effect})
this.item.update({name: this.item.setSpecifier(effectName)});
this.script.notification(effectName);

let unarmed = (await fromUuid("Compendium.impmal-core.items.Item.2m5Y4NrByRHla6xk")).toObject();

unarmed.name = this.effect.name;

unarmed.system.traits.list.push({key: "reach"})
unarmed.system.traits.list.push({key: "inflict", value: "restrained"});

this.actor.createEmbeddedDocuments("Item", [unarmed], {fromEffect: this.effect.id});

let roll = await new Roll("2d10").roll()
roll.toMessage(this.script.getChatData())
this.actor.applyDamage(roll.total, {message: true})

if (args.type == "effect" && args.options.action == "create" && ["fatigued", "frightened", "stunned"].some(i => args.document.statuses.has(i)))
{
  this.script.notification("Immune to " + args.document.name);
  return false;
}

let activated = await foundry.applications.api.Dialog.confirm({
  window : {title : this.effect.name },
  content : `<p>Activate ${this.effect.name}? (+5 SL to WS and Strength)`
})

this.effect.setFlag("impmal", "activated", activated)

if (this.effect.getFlag("impmal", "activated")){
  this.actor.applyDamage(5,{ignoreAP: true, message: true})
  this.effect.setFlag("impmal", "activated", false)
}

if (args.type == "effect" && args.options.action == "create" && ["dark", "poorlyLit"].some(i => args.document.statuses.has(i)))
{
  this.script.notification("Immune to " + args.document.name);
  return false;
}

